}

// TestRunner_Execute_HappyPath runs a fake script that emits codex-style JSONL.
func TestRunner_Execute_HappyPath(t *testing.T) {
	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	// Write a fake "codex" script.
	script := `#!/bin/sh
cat <<'EOF'
{"type":"output","item":{"type":"agent_message","text":"hello from codex"}}
{"type":"turn.completed","usage":{"input_tokens":10,"output_tokens":5}}
EOF
`
	f, err := os.CreateTemp("", "fake-codex-*")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(f.Name())
	if _, err := f.WriteString(script); err != nil {
		t.Fatal(err)
	}
	f.Close()
	if err := os.Chmod(f.Name(), 0o755); err != nil {
		t.Fatal(err)
	}

	r := &Runner{
		Binary:   f.Name(),
		BaseArgs: []string{}, // skip "exec --json" so the script runs cleanly
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	ch, err := r.Execute(ctx, harnesses.ExecuteRequest{
		Prompt: "test prompt",
	})
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}

	var textDeltas []string
	var finalEv *harnesses.FinalData
	for ev := range ch {
		switch ev.Type {
		case harnesses.EventTypeTextDelta:
			var d harnesses.TextDeltaData
			if err := json.Unmarshal(ev.Data, &d); err != nil {
				t.Errorf("unmarshal text_delta: %v", err)
			}
			textDeltas = append(textDeltas, d.Text)
		case harnesses.EventTypeFinal:
			var fd harnesses.FinalData
			if err := json.Unmarshal(ev.Data, &fd); err != nil {
				t.Errorf("unmarshal final: %v", err)
			}
			finalEv = &fd
		}
	}

	if len(textDeltas) == 0 {
		t.Error("expected at least one text_delta event")
	} else if !strings.Contains(textDeltas[0], "hello from codex") {
		t.Errorf("unexpected text delta: %q", textDeltas[0])
	}

	if finalEv == nil {
		t.Fatal("no final event received")
	}
	if finalEv.Status != "success" {
		t.Errorf("expected status=success, got %q (error: %s)", finalEv.Status, finalEv.Error)
	}
	if finalEv.FinalText != "hello from codex" {
		t.Errorf("expected FinalText=%q, got %q", "hello from codex", finalEv.FinalText)
	}
	if finalEv.Usage == nil {
		t.Error("expected usage in final event")
	} else {
		if finalEv.Usage.InputTokens == nil || *finalEv.Usage.InputTokens != 10 {
			t.Errorf("expected InputTokens=10, got %#v", finalEv.Usage.InputTokens)
		}
		if finalEv.Usage.OutputTokens == nil || *finalEv.Usage.OutputTokens != 5 {
			t.Errorf("expected OutputTokens=5, got %#v", finalEv.Usage.OutputTokens)
		}
		if finalEv.Usage.TotalTokens == nil || *finalEv.Usage.TotalTokens != 15 {
			t.Errorf("expected TotalTokens=15, got %#v", finalEv.Usage.TotalTokens)
		}
	}
}

func TestRunner_Execute_UpdatesQuotaCacheFromTokenCountRateLimits(t *testing.T) {
	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}
	dir := t.TempDir()
	t.Setenv(codexQuotaCacheEnv, filepath.Join(dir, "codex-quota.json"))

	cmd := harnesses.HarnessCommand(runCtx, binary, args...)
	if req.WorkDir != "" {
		cmd.Dir = req.WorkDir
	}
	if promptMode != "arg" {
		cmd.Stdin = strings.NewReader(req.Prompt)
	}
	setProcessGroup(cmd)

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		return nil, -1, "", err, "failed"
	}
	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		return nil, -1, "", err, "failed"
	}

	if err := cmd.Start(); err != nil {
		return nil, -1, "", err, "failed"
	}

	progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "codex")
	if progressLog != nil {
		defer progressLog.Close()
	}

	parserReader, parserWriter := io.Pipe()
	parseDone := make(chan struct{})
	var parseAgg *streamAggregate
	var parseErr error
	go func() {
		defer close(parseDone)
		mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
		defer func() {
			close(mirrored)
			<-mirrorDone
		}()
		parseAgg, parseErr = parseCodexStream(runCtx, parserReader, mirrored, req.Metadata, seq)
	}()

	stdoutDone := make(chan struct{})
	go func() {
		defer close(stdoutDone)
		_, _ = io.Copy(parserWriter, stdoutPipe)
		_ = parserWriter.Close()
	}()

	var stderrBuf strings.Builder
	stderrDone := make(chan struct{})
	go func() {
		defer close(stderrDone)
		_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
	}()

	var timedOut bool
	if req.Timeout > 0 {
		stop := make(chan struct{})
		go func() {
			select {
			case <-stop:
			case <-time.After(req.Timeout):
				timedOut = true
				cancel()
			}
		}()
		defer close(stop)
	}

	cancelDone := make(chan struct{})
	go func() {
		defer close(cancelDone)
		select {
		case <-ctx.Done():
			killProcessGroup(cmd)
		case <-stdoutDone:
		}
	}()

	<-stdoutDone
	<-stderrDone
	<-parseDone
	runErr = cmd.Wait()
	<-cancelDone
	stderr = stderrBuf.String()

	switch {
	case timedOut:
		return parseAgg, -1, stderr, context.DeadlineExceeded, "timed_out"
	case ctx.Err() != nil && errors.Is(ctx.Err(), context.Canceled):
		return parseAgg, -1, stderr, ctx.Err(), "cancelled"
	case ctx.Err() != nil && errors.Is(ctx.Err(), context.DeadlineExceeded):
		return parseAgg, -1, stderr, ctx.Err(), "timed_out"
	case runErr != nil:
		ec := -1
		var exitErr *osexec.ExitError
		if errors.As(runErr, &exitErr) {
			ec = exitErr.ExitCode()
		}
		return parseAgg, ec, stderr, runErr, "failed"
	}
	if parseErr != nil && !errors.Is(parseErr, context.Canceled) {
		return parseAgg, 0, stderr, parseErr, "failed"
	}
	return parseAgg, 0, stderr, nil, "success"
}

type stringBuilderWriter struct {
	sb *strings.Builder
}

func (w *stringBuilderWriter) Write(p []byte) (int, error) {
	return w.sb.Write(p)
}

func trimErrorBlob(s string) string {
	const max = 2048
	s = strings.TrimSpace(s)
	if len(s) > max {
		return s[:max] + "...(truncated)"
	}
	return s
}

func setProcessGroup(cmd *osexec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	setProcessGroupAttr(cmd.SysProcAttr)
}

package codex

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"strconv"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
)

// codexEvent is a minimal view of a codex exec --json JSONL event.
// Codex emits one JSON object per line on stdout.
//
// Observed event types (from DDx ExtractUsage and ExtractOutput):
//
//	type=output, item.type=agent_message, item.text=<response text>
//	type=turn.completed, usage.input_tokens=N, usage.output_tokens=N
//	type=event_msg, payload.type=token_count, payload.info.last_token_usage=...
//	(other types are passed through silently)
type codexEvent struct {
	Type   string `json:"type"`
	Source string `json:"source"`
	Fresh  *bool  `json:"fresh"`
	Item   struct {
		ID               string          `json:"id"`
		Type             string          `json:"type"`
		Text             string          `json:"text"`
		Content          json.RawMessage `json:"content"`
		Command          string          `json:"command"`
		AggregatedOutput string          `json:"aggregated_output"`
		ExitCode         *int            `json:"exit_code"`
		Status           string          `json:"status"`
	} `json:"item"`
	Usage      json.RawMessage `json:"usage"`
	CapturedAt string          `json:"captured_at"`
	Timestamp  string          `json:"timestamp"`
	Payload    struct {
		Type string `json:"type"`
		Info struct {
			LastTokenUsage json.RawMessage `json:"last_token_usage"`
			RateLimits     json.RawMessage `json:"rate_limits"`
		} `json:"info"`
		RateLimits json.RawMessage `json:"rate_limits"`
	} `json:"payload"`
}

// tokenCountRateLimitEvidence preserves structured Codex quota evidence from
// token_count events for a later service integration step.
type tokenCountRateLimitEvidence struct {
	CapturedAt string
	RateLimits json.RawMessage
}

// streamAggregate captures running totals from the codex stream.
type streamAggregate struct {
	FinalText            string
	UsageSources         []harnesses.UsageCandidate
	TokenCountRateLimits []tokenCountRateLimitEvidence
}

// parseCodexStream reads newline-delimited codex exec --json events from r
// and emits harness Events on out. Mapping per CONTRACT-003:
//
//   - codex output/agent_message              -> EventTypeTextDelta
//   - codex item.started command_execution    -> EventTypeToolCall
//   - codex item.completed command_execution  -> EventTypeToolResult
//   - codex item.completed text item          -> EventTypeTextDelta
//   - codex turn.completed                    -> (no event; aggregate populated with usage)
//   - codex event_msg token_count             -> (no event; aggregate populated with usage/quota evidence)
//   - all other types                         -> skipped
func parseCodexStream(ctx context.Context, r io.Reader, out chan<- harnesses.Event, metadata map[string]string, seq *int64) (*streamAggregate, error) {
	agg := &streamAggregate{}
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 0, 256*1024), 16*1024*1024)

	emit := func(t harnesses.EventType, data any) error {
		raw, err := json.Marshal(data)
		if err != nil {
			return err
		}
		ev := harnesses.Event{
			Type:     t,
			Sequence: *seq,
			Time:     time.Now().UTC(),
			Metadata: metadata,
			Data:     raw,
		}
		*seq++
		select {
		case out <- ev:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}

	for scanner.Scan() {
		select {
		case <-ctx.Done():
			return agg, ctx.Err()
		default:
		}

		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var ev codexEvent
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			// Non-JSON line — skip silently.
			continue
		}

		switch ev.Type {
		case "output":
			if ev.Item.Type == "agent_message" && ev.Item.Text != "" {
				if err := emit(harnesses.EventTypeTextDelta, harnesses.TextDeltaData{Text: ev.Item.Text}); err != nil {
					return agg, err
				}
				agg.FinalText = ev.Item.Text
			}
		case "item.completed":
			if ev.Item.Type == "command_execution" {
				if err := emit(harnesses.EventTypeToolResult, harnesses.ToolResultData{
					ID:     codexToolID(ev.Item.ID),
					Output: ev.Item.AggregatedOutput,
					Error:  codexCommandError(ev.Item.Status, ev.Item.ExitCode),
				}); err != nil {
					return agg, err
				}
				continue
			}
			text := codexCompletedItemText(ev.Item.Text, ev.Item.Content)
			if text != "" {
				if err := emit(harnesses.EventTypeTextDelta, harnesses.TextDeltaData{Text: text}); err != nil {
					return agg, err
				}
				agg.FinalText = text
			}
		case "item.started":
			if ev.Item.Type == "command_execution" {
				input, err := codexCommandInput(ev.Item.Command)
				if err != nil {
					return agg, err
				}
				if err := emit(harnesses.EventTypeToolCall, harnesses.ToolCallData{
					ID:    codexToolID(ev.Item.ID),
					Name:  "bash",
					Input: input,
				}); err != nil {
					return agg, err
				}
			}
		case "turn.completed":
			agg.recordUsage(ev.Usage)
		case "event_msg":
			if ev.Payload.Type == "token_count" {
				agg.recordTokenCountUsage(ev.Timestamp, ev.Payload.Info.LastTokenUsage, codexTokenCountRateLimitsRaw(ev.Payload.RateLimits, ev.Payload.Info.RateLimits))
			}
		case "ddx.usage_source":
			agg.recordUsageSource(ev.Source, ev.Fresh, ev.CapturedAt, ev.Usage)
		}
	}
	if err := scanner.Err(); err != nil && !errors.Is(err, io.EOF) {
		return agg, err
	}
	return agg, nil
}

func (a *streamAggregate) recordUsage(raw json.RawMessage) {
	a.recordUsageSource(harnesses.UsageSourceNativeStream, harnesses.BoolPtr(true), "", raw)
}

func (a *streamAggregate) recordTokenCountUsage(capturedAt string, usage json.RawMessage, rateLimits json.RawMessage) {
	a.recordUsageSource(harnesses.UsageSourceNativeTokenCount, harnesses.BoolPtr(true), capturedAt, usage)
	if len(rateLimits) == 0 || string(rateLimits) == "null" {
		return
	}
	copied := append(json.RawMessage(nil), rateLimits...)
	a.TokenCountRateLimits = append(a.TokenCountRateLimits, tokenCountRateLimitEvidence{
		CapturedAt: capturedAt,
		RateLimits: copied,
	})
}

func codexTokenCountRateLimitsRaw(candidates ...json.RawMessage) json.RawMessage {
	for _, raw := range candidates {
		if len(raw) == 0 || string(raw) == "null" {
			continue
		}
		return raw
	}
	return nil
}

func (a *streamAggregate) recordUsageSource(source string, fresh *bool, capturedAt string, raw json.RawMessage) {
	if len(raw) == 0 || string(raw) == "null" {
		return
	}
	if source == "" {
		source = harnesses.UsageSourceFallback
	}
	counts, err := harnesses.ParseUsageJSON(raw)
	if err != nil {
		a.UsageSources = append(a.UsageSources, harnesses.UsageCandidate{
			Source:     source,
			Fresh:      fresh,
			CapturedAt: capturedAt,
			Warning:    err.Error(),
		})
		return
	}
	if counts.Any() {
		a.UsageSources = append(a.UsageSources, harnesses.UsageCandidate{
			Source:     source,
			Fresh:      fresh,
			CapturedAt: capturedAt,
			Counts:     counts,
		})
	}
}

func codexToolID(id string) string {
	if id != "" {
		return id
	}
	return "codex-command"
}

func codexCommandInput(command string) (json.RawMessage, error) {
	raw, err := json.Marshal(map[string]string{"command": command})
	return raw, err
}

func codexCommandError(status string, exitCode *int) string {
	if exitCode != nil && *exitCode != 0 {
		return "exit status " + strconv.Itoa(*exitCode)
	}
	if status != "" && status != "completed" {
		return status
	}
	return ""
}

func codexCompletedItemText(text string, content json.RawMessage) string {
	if text != "" {
		return text
	}
	if len(content) == 0 {
		return ""
	}
	var contentString string
	if err := json.Unmarshal(content, &contentString); err == nil {
		return contentString
	}

	}
	var blocks []struct {
		Text    string `json:"text"`
		Content string `json:"content"`
	}
	if err := json.Unmarshal(content, &blocks); err != nil {
		return ""
	}
	var b strings.Builder
	for _, block := range blocks {
		if block.Text != "" {
			b.WriteString(block.Text)
		} else if block.Content != "" {
			b.WriteString(block.Content)
		}
	}
	return b.String()
}

